# fmt: on


def _build(rows: list, difficulty: str) -> list[dict]:
    out = []
    for q, ch, ans, exp, tags in rows:
        out.append(
            {
                "question": q,
                "choices": ch,
                "answer": ans,
                "explanation": exp,
                "tags": tags,
                "difficulty": difficulty,
            }
        )
    return out


def main() -> None:
    items = (
        _build(EASY, "Easy")
        + _build(MEDIUM, "Medium")
        + _build(HARD, "Hard")
    )

    # Assign sequential IDs and merge base fields
    final = []
    for idx, item in enumerate(items, start=1):
        entry = {"id": idx, **B, **item}
        final.append(entry)

    # Validate counts
    easy_count = sum(1 for x in final if x["difficulty"] == "Easy")
    med_count = sum(1 for x in final if x["difficulty"] == "Medium")
    hard_count = sum(1 for x in final if x["difficulty"] == "Hard")
    total = len(final)

    print(f"Easy: {easy_count}, Medium: {med_count}, Hard: {hard_count}, Total: {total}")

    if total != 600:
        print(f"WARNING: Expected 600 questions, got {total}")

    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(
        json.dumps(final, indent=2, ensure_ascii=False), encoding="utf-8"
    )
    print(f"Written to {OUTPUT}")


if __name__ == "__main__":
    main()
